  def update_ball
    case @step
    when 1
      @other_ball_x=155
      @ball_x=114
      @main_window.contents.draw_text(@ball_x,56,32,32,"◎")
      @main_window.contents.draw_text(@other_ball_x,283,32,32,"◎")
    when 2
      case @dir
      when 1
        @ball_x+=rand(4)+1
        @dir=2 if @ball_x>=178
      when 2
        @ball_x-=rand(4)+1
        @dir=1 if @ball_x<=53
      end
      @main_window.contents.draw_text(@ball_x,56,32,32,"◎")
      @main_window.contents.draw_text(@other_ball_x,283,32,32,"◎")
    when 3
      @main_window.contents.draw_text(@ball_x,56,32,32,"◎")
      y=get_ball_y
      @main_window.contents.draw_text(@other_ball_x,y,32,32,"◎")
      @other_ball_x+=2 if @other_ball_x<375
      #@main_window.contents.draw_text(375,100,32,32,"◎")
    end
  end
  def get_ball_y
    if @other_ball_x==155
      @other_ball_y=100
      return 283
    end
    if @other_ball_x==375
      @other_ball_y+=2
      @step=1 if @other_ball_y>=283
      return @other_ball_y
    end
    ss=(375-@other_ball_x)**2
    ss*=0.004162330905
    return ss+95
  end
end

